import os

def check_file(path):
    if os.path.exists(path):
        if os.path.isfile(path):
            print('The path exists and is a file.')
        else:
            print('The path exists but is a directory.')
    else:
        print('The path does not exist.')

# Example usage
check_file('example.txt')

import os

def absolute_files(paths):
    result = []
    for p in paths:
        if os.path.isfile(p):
            result.append(os.path.abspath(p))
    return result

paths = ['data/report.csv', 'logs/', 'README.md', 'scripts/']
print(absolute_files(paths))
